USERS = {1: {'id': 1, 'name': 'Ada', 'email': 'ada@example.com'}}


def get_user(user_id):
    user = USERS.get(user_id)
    if user is None:
        return 400, {'error': 'bad request'}
    return 200, {'id': user['id'], 'name': user['name']}


def create_user(body):
    user_id = max(USERS) + 1
    USERS[user_id] = {'id': user_id, **body}
    return 201, USERS[user_id]


ROUTES = {('GET', '/users/{id}'): get_user, ('POST', '/users'): create_user}
